SELECT ,
       (SELECT COUNT(*) FROM dist_requisition_item i WHERE i.requisition_id = r.id) AS item_count
FROM dist_requisition r



        (r.req_no LIKE CONCAT('%', #{q.keyword}, '%') OR r.remark LIKE CONCAT('%', #{q.keyword}, '%'))


        AND r.status IN #{st}

    AND (r.store_id = #{q.storeId} OR r.supply_store_id = #{q.storeId})
    AND r.store_id = #{q.toStoreId}
    AND r.supply_warehouse_id = #{q.warehouseId}
    AND r.biz_date >= #{q.begin}
    AND r.biz_date <= #{q.end}

        AND EXISTS (SELECT 1 FROM dist_requisition_item x WHERE x.requisition_id = r.id AND x.material_id = #{q.materialId})


ORDER BY r.id DESC

SELECT 
FROM dist_requisition r

WHERE r.id = #{id}

SELECT m.id AS material_id, COALESCE(l.min_qty, m.safety_stock, 0) AS min_qty, (SELECT COALESCE(SUM(s.qty), 0) FROM wms_stock s WHERE s.warehouse_id = #{warehouseId} AND s.material_id = m.id) AS stock_qty, (SELECT COALESCE(SUM(ti.qty), 0) FROM wms_stock_doc_item ti JOIN wms_stock_doc td ON td.id = ti.doc_id WHERE td.kind = 'TRANSFER' AND td.status = 'TRANSIT' AND td.to_warehouse_id = #{warehouseId} AND ti.material_id = m.id) AS transit_qty,
(SELECT COALESCE(SUM(s.qty - s.frozen_qty), 0) FROM wms_stock s WHERE s.warehouse_id = #{supplyWarehouseId} AND s.material_id = m.id)
NULL AS supply_available FROM wms_material m LEFT JOIN wms_material_warehouse_limit l ON l.material_id = m.id AND l.warehouse_id = #{warehouseId} WHERE m.id IN #{mid}
